#include "mount_auditor/api.hpp"
#include <algorithm>
#include <csignal>
#include <iostream>
#include <map>
#include <set>

namespace {
constexpr const char* help="linux-mount-auditor 1.0.0 - read-only Linux mount auditor\n\nUsage: linux-mount-auditor COMMAND [OPTIONS] [TARGET]\nCommands: inspect, tree, show, fstab, compare, audit, check, help, version\nOptions: --json  --all  --include-pseudo  --type TYPE  --source SOURCE\n         --target TARGET  --fstab PATH  --mountinfo PATH\nExit codes: 0 success; 1 findings/check issue; 2 usage; 3 data unavailable; 4 malformed/incomplete data; 5 internal/resource error\n";
bool pseudo(const lma::Mount&m){return m.classification=="pseudo/virtual kernel filesystem"||m.classification=="tmpfs/ram-backed";}
void diagnostics(const std::vector<lma::Diagnostic>&d){for(const auto&x:d){std::cerr<<x.level<<": "<<x.source;if(x.line!=0)std::cerr<<':'<<x.line;std::cerr<<": "<<x.message<<'\n';}}
void print_mount(const lma::Mount&m){std::cout<<m.target<<" <- "<<m.source<<" ["<<m.fs_type<<", "<<(m.read_only?"ro":"rw")<<", "<<m.classification<<", "<<m.propagation<<"] id="<<m.id<<" parent="<<m.parent_id;if(m.sysfs_device)std::cout<<" device="<<*m.sysfs_device;if(m.device_mapper_name)std::cout<<" dm="<<*m.device_mapper_name;if(m.partition_parent)std::cout<<" partition-of="<<*m.partition_parent;if(m.removable)std::cout<<" removable="<<(*m.removable?"yes":"no");if(m.rotational)std::cout<<" rotational="<<(*m.rotational?"yes":"no");std::cout<<'\n';}
void tree_node(std::uint64_t id,std::size_t depth,const std::map<std::uint64_t,const lma::Mount*>&by,const lma::Hierarchy&h,std::set<std::uint64_t>&seen){if(depth>lma::kMaxDepth||seen.count(id))return;seen.insert(id);auto it=by.find(id);if(it==by.end())return;std::cout<<std::string(std::min<std::size_t>(depth,64)*2,' ')<<it->second->target<<" ("<<it->second->fs_type<<", id="<<id<<")\n";auto c=h.children.find(id);if(c!=h.children.end())for(auto child:c->second)tree_node(child,depth+1,by,h,seen);}
}
int main(int argc,char**argv){
 std::signal(SIGPIPE,SIG_IGN);if(argc<2){std::cerr<<help;return 2;}std::string command=argv[1];if(command=="help"||command=="--help"){std::cout<<help;return 0;}if(command=="version"||command=="--version"){std::cout<<"linux-mount-auditor 1.0.0\n";return 0;}
 const std::set<std::string> commands={"inspect","tree","show","fstab","compare","audit","check"};if(!commands.count(command)){std::cerr<<"error: unknown command: "<<command<<'\n';return 2;}
 bool json=false,all=false,include_pseudo=false;std::string mount_path="/proc/self/mountinfo",fstab_path="/etc/fstab",type,source,target,show_arg;
 for(int i=2;i<argc;++i){std::string a=argv[i];auto val=[&](std::string&dst){if(i+1>=argc){std::cerr<<"error: missing value for "<<a<<'\n';return false;}dst=argv[++i];return true;};if(a=="--json")json=true;else if(a=="--all")all=true;else if(a=="--include-pseudo")include_pseudo=true;else if(a=="--type"){if(!val(type))return 2;}else if(a=="--source"){if(!val(source))return 2;}else if(a=="--target"){if(!val(target))return 2;}else if(a=="--fstab"){if(!val(fstab_path))return 2;}else if(a=="--mountinfo"){if(!val(mount_path))return 2;}else if(command=="show"&&show_arg.empty())show_arg=a;else{std::cerr<<"error: unexpected argument: "<<a<<'\n';return 2;}}
 std::vector<lma::Diagnostic> diags;std::string error;auto raw=lma::read_bounded_file(mount_path,lma::kMaxInput,error);lma::ParseResult<lma::Mount> mp;if(raw)mp=lma::parse_mountinfo(*raw);else diags.push_back({"error","mountinfo",error,0});diags.insert(diags.end(),mp.diagnostics.begin(),mp.diagnostics.end());if(mount_path=="/proc/self/mountinfo")lma::enrich_block_devices(mp.records,diags);
 std::string ferr;auto fr=lma::read_bounded_file(fstab_path,lma::kMaxInput,ferr);lma::ParseResult<lma::FstabEntry> fp;if(fr)fp=lma::parse_fstab(*fr);else diags.push_back({"warning","fstab",ferr,0});diags.insert(diags.end(),fp.diagnostics.begin(),fp.diagnostics.end());lma::resolve_identifiers(fp.records,diags);
 std::vector<lma::Mount> mounts;mounts.reserve(mp.records.size());for(const auto&m:mp.records){const bool excluded=(!all&&((!include_pseudo&&pseudo(m))||(!type.empty()&&m.fs_type!=type)||(!source.empty()&&m.source!=source)||(!target.empty()&&m.target!=target)));if(!excluded)mounts.push_back(m);}
 if(command=="fstab"){if(json)lma::render_fstab_json(std::cout,fp.records,diags);else{for(const auto&f:fp.records)std::cout<<f.spec<<" on "<<f.target<<" type "<<f.fs_type<<" ("<<lma::join(f.options,",")<<") line "<<f.line<<'\n';diagnostics(diags);}return fr?(fp.complete?0:4):3;}
 if(!raw){if(json)lma::render_mounts_json(std::cout,{},diags);else diagnostics(diags);return 3;}
 if(command=="inspect"){if(json)lma::render_mounts_json(std::cout,mounts,diags);else{for(const auto&m:mounts)print_mount(m);diagnostics(diags);}return mp.complete?0:4;}
 if(command=="show"){if(show_arg.empty()&&!target.empty())show_arg=target;if(show_arg.empty()){std::cerr<<"error: show requires TARGET\n";return 2;}std::vector<lma::Mount> found;std::size_t best=0;for(const auto&m:mp.records)if(lma::path_beneath(show_arg,m.target)&&m.target.size()>=best){if(m.target.size()>best){found.clear();best=m.target.size();}found.push_back(m);}if(json)lma::render_mounts_json(std::cout,found,diags);else{for(const auto&m:found)print_mount(m);diagnostics(diags);}return found.empty()?1:0;}
 if(command=="tree"){auto h=lma::build_hierarchy(mp.records);diags.insert(diags.end(),h.diagnostics.begin(),h.diagnostics.end());if(json)lma::render_mounts_json(std::cout,mp.records,diags);else{std::map<std::uint64_t,const lma::Mount*>by;for(const auto&m:mp.records)by[m.id]=&m;std::set<std::uint64_t>seen;for(auto id:h.roots)tree_node(id,0,by,h,seen);for(const auto&m:mp.records)if(!seen.count(m.id))tree_node(m.id,0,by,h,seen);diagnostics(diags);}const bool malformed=std::any_of(h.diagnostics.begin(),h.diagnostics.end(),[](const auto&d){return d.level=="error";});return malformed?4:0;}
 auto cmp=lma::compare(mp.records,fp.records,static_cast<bool>(fr));if(command=="compare"){if(json)lma::render_compare_json(std::cout,cmp,diags);else{for(const auto&c:cmp)std::cout<<c.status<<": "<<c.target<<": "<<c.detail<<'\n';diagnostics(diags);}return (!mp.complete||!fp.complete)?4:0;}
 auto findings=lma::audit(mp.records,fp.records,cmp,diags);if(command=="audit"||command=="check"){if(json)lma::render_audit_json(std::cout,findings,diags);else{if(findings.empty())std::cout<<"No review findings.\n";for(const auto&f:findings)std::cout<<f.severity<<" ["<<f.category<<"] "<<f.subject<<": "<<f.message<<'\n';diagnostics(diags);}bool warn=std::any_of(findings.begin(),findings.end(),[](const auto&f){return f.severity=="warning";});return command=="check"&&warn?1:((!mp.complete||!fp.complete)?4:0);}
 return 5;
}
